FILE: app/src/release.ts
```ts
import { getAnimationGroups, stopAnimation } from "@babylonjs/lite";
import type { AnimationManager, AnimationGroup } from "@babylonjs/lite";

export function releaseProperty(manager: AnimationManager, target: object, path: string): void {
    const groups = getAnimationGroups(manager);
    for (let i = 0; i < groups.length; i++) {
        if (animatesProperty(groups[i], target, path)) {
            stopAnimation(groups[i]);
        }
    }
}

function animatesProperty(group: AnimationGroup, target: object, path: string): boolean {
    const segments = path.split(".");
    const last = segments[segments.length - 1];
    let parent: object = target;
    for (let i = 0; i < segments.length - 1; i++) {
        parent = (parent as Record<string, unknown>)[segments[i]] as object;
        if (parent == null) return false;
    }
    const targeted = group.targetedAnimations;
    for (let i = 0; i < targeted.length; i++) {
        if (targeted[i].target === parent && targeted[i].path === last) {
            return true;
        }
    }
    return false;
}
```

I wrote `src/release.ts` which iterates the manager's groups via `getAnimationGroups`, resolves the user's dotted path to its parent object and last segment, and stops (via `stopAnimation`) every group whose `targetedAnimations` contain an entry matching both — so that no remaining group writes to that property while all non-matching groups continue untouched. I was not sure whether you intended a group that animates the target property *and* other properties to be stopped wholesale (it is, since the API only stops whole groups) or whether a weight-0 group should be exempted (it is not, but that's harmless since it wasn't writing anyway).
